import{_ as e,o as s,c as i,ae as n}from"./chunks/framework.DBosx3SP.js";const u=JSON.parse('{"title":"Tick Labeling","description":"","frontmatter":{},"headers":[],"relativePath":"ux/tick-labeling.md","filePath":"ux/tick-labeling.md","lastUpdated":1792899449000}'),l={name:"ux/tick-labeling.md"};function t(c,a,o,p,r,d){return s(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="tick-labeling" tabindex="-1">Tick Labeling <a class="header-anchor" href="#tick-labeling" aria-label="Permalink to &quot;Tick Labeling&quot;">​</a></h1><h2 id="linear-scale" tabindex="-1">Linear Scale <a class="header-anchor" href="#linear-scale" aria-label="Permalink to &quot;Linear Scale&quot;">​</a></h2><p>Extended Wilkinson is a clear winner.</p><h2 id="log-scale" tabindex="-1">Log Scale <a class="header-anchor" href="#log-scale" aria-label="Permalink to &quot;Log Scale&quot;">​</a></h2><p>EplusM is a good modern alternative to LogScale.</p><p>For both LogScale and EplusMScale, we still have to decide:</p><ul><li><code>10^0, 10^1, 10^2</code> or <code>1, 10, 100, 1000, 10000</code>, or <code>1, 10, 100, 1k, 10k, 100k, 1m</code> or raw <code>1, 10, 100, 1,000, 10,000, 100,000, ..</code></li><li>smaller numbers (<code>0.1, 0.01, 0.001</code>)</li><li>centered log (<code>0.99, 0.999, 0.9999, 1.0</code>)</li><li>different log base (<code>1, 2, 4, 8, 16, 32, 64</code>)</li></ul><p>Decisions:</p><ul><li>Use base 10 by default</li><li>Use scientific for <code>|x|&gt;10^7</code></li><li>SI? Scientific? Unit?</li></ul><h2 id="label-formatting" tabindex="-1">Label Formatting <a class="header-anchor" href="#label-formatting" aria-label="Permalink to &quot;Label Formatting&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scale.format.comma = true;       // incompatible with si</span></span>
<span class="line"><span>scale.format.si = true;          // incompatible with time unit</span></span>
<span class="line"><span>scale.format.scientific = 8;     // use 10^x since |x|&gt;=8. 0 means no scientific notation.</span></span>
<span class="line"><span>scale.format.unit = Unit::Bytes1024</span></span></code></pre></div><p>Possible combinations:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  SI | Comma | Scientific</span></span>
<span class="line"><span>  ------------------------</span></span>
<span class="line"><span>   O     X         X</span></span>
<span class="line"><span>   X     x         X</span></span>
<span class="line"><span>   X     O         X</span></span>
<span class="line"><span>   X     X         O</span></span>
<span class="line"><span>   X     O         O</span></span></code></pre></div><p>It gets complicated further by</p><ul><li>irregular units (seconds -&gt; minutes -&gt; hours -&gt; days)</li><li>nice number generation considering the formatting and centering</li><li>Easy presets for common cases, such as <ul><li><code>Bytes1024</code> (1KiB) IEC - <code>comma=false, scientific=0, custom_units=[(&#39;K&#39;,1024),(&#39;M&#39;,1048576),..]</code></li><li><code>Bytes1000</code> (1KB) SI - <code>si=true, comma=false, scientific=0</code></li><li><code>Duration</code> (<code>1ns, 1us, 1ms, 130ms, 5s, 140s, 2m 5s, 250m, 4h 1m 5s</code>) with min/max units</li></ul></li></ul>`,15)])])}const g=e(l,[["render",t]]);export{u as __pageData,g as default};
